/* MODULE kn03 · Bước 5 Chọn kênh · Sàn TMĐT: Shopee, Lazada, TikTok Shop
   10 bài × 7 câu. Tên sàn được nêu như ví dụ công khai; mọi mức phí, tỉ lệ và con số đều là MINH HOẠ, tự khớp nhau, không phải biểu phí thật của sàn nào. */
BAI_ADD({ mod:'kn03', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kn03-01', skill:'channel', read:'6 phút', t:'Mới bán online với 30 triệu: lên sàn nào trước?',
  situation:'Chị Hà làm xà phòng thủ công ở Đà Lạt, bán qua Facebook được khoảng 150 đơn mỗi tháng. Chị có 30 triệu và thời gian của hai người để lên sàn. Bạn bè khuyên mở cùng lúc Shopee, Lazada và TikTok Shop "cho phủ". Chị không có ai quay video, nhưng có sẵn 40 bài đánh giá tốt từ khách cũ và bộ ảnh sản phẩm đẹp.',
  concept:{ name:'Sàn tìm kiếm và sàn khám phá',
    body:'Sàn thiên về <b>tìm kiếm</b> phục vụ người đã biết mình cần gì: họ gõ "xà phòng handmade", so giá, đọc đánh giá rồi mua. Sàn thiên về <b>khám phá</b> đẩy video và livestream đến người chưa định mua; nhu cầu được tạo ngay trên màn hình. Mỗi kiểu đòi một năng lực khác: sàn tìm kiếm cần trang sản phẩm, đánh giá và giá rõ; sàn khám phá cần nội dung đều đặn. Nguồn lực mỏng thì chọn một sàn khớp với năng lực mình đang có, làm cho ra đơn đều, rồi mới mở sàn thứ hai.' },
  example:'Chị Hà có ảnh đẹp và đánh giá sẵn, không có người làm video. Mở cả ba sàn, 30 triệu chia ba còn 10 triệu mỗi nơi, hai người phải trả lời tin nhắn, đóng gói và làm nội dung cho ba chỗ. Chọn một sàn thiên tìm kiếm trước, dồn 30 triệu vào quảng cáo từ khoá và vài đợt đánh giá đầu, mục tiêu 5 đơn/ngày trong 60 ngày. Khi đạt, chị thuê một bạn quay video và thử sàn khám phá.',
  takeaway:'Sàn đầu tiên là sàn khớp với năng lực bạn đang có, không phải sàn đang được bàn nhiều nhất.',
  apply:'Liệt kê ba thứ bạn đang giỏi (ảnh, video, giá, dịch vụ). Nói trong 60 giây: sàn nào dùng được nhiều nhất trong ba thứ đó và vì sao.',
  mistakes:['Mở cùng lúc nhiều sàn khi chưa có đơn đều ở sàn nào.','Chọn sàn theo độ nóng thay vì theo năng lực nội dung của mình.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với 30 triệu và hai người, mở cùng lúc ba sàn thường dẫn đến điều gì?',
    options:[{k:'a',t:'Phủ rộng nên tổng đơn gấp ba so với chỉ làm một sàn duy nhất'},{k:'b',t:'Nguồn lực bị chia mỏng, không sàn nào đủ đơn để được đẩy lên'},
             {k:'c',t:'Sàn nào cũng tự đẩy shop mới nên chưa cần tiền quảng cáo'},{k:'d',t:'Khách thấy shop ở nhiều sàn sẽ tin hơn và mua nhiều hơn'}],
    answer:'b', why:{a:'Đơn không cộng tuyến tính theo số sàn; mỗi sàn cần ngân sách và công sức riêng để có đơn đầu tiên.',
      b:'Đúng. Mỗi sàn chỉ còn 10 triệu và một phần ba công sức, khó vượt ngưỡng đơn đều để thuật toán chú ý.',
      c:'Hỗ trợ shop mới nếu có thường ngắn và nhỏ; không thay được ngân sách kéo đơn đầu.',
      d:'Khách thường mua trong một sàn, ít đi kiểm tra shop có mặt ở sàn khác.'} },
  { type:'mcq', stem:'Chị Hà có ảnh đẹp, 40 đánh giá, không có người quay video. Bạn chọn gì cho 60 ngày đầu?',
    options:[{k:'a',t:'Mở TikTok Shop trước vì đang tăng nhanh, rồi tự học quay video dần'},{k:'b',t:'Mở đủ ba sàn nhưng chỉ đăng 5 sản phẩm mỗi sàn cho nhẹ việc'},
             {k:'c',t:'Một sàn thiên tìm kiếm, dồn tiền vào từ khoá, đích 5 đơn/ngày'},{k:'d',t:'Chưa lên sàn, dồn 30 triệu chạy quảng cáo Facebook cho quen tay'}],
    answer:'c', why:{a:'Sàn khám phá sống bằng video đều đặn; tự học trong lúc đốt tiền là đặt cược vào năng lực chưa có.',
      b:'Giảm số sản phẩm không giảm việc vận hành ba nơi; tiền vẫn bị chia ba.',
      c:'Đúng. Dùng đúng thứ đang có (ảnh, đánh giá), đo được bằng một mục tiêu rõ.',
      d:'Facebook đã chạy được; câu hỏi là mở kênh mới nào, không phải bỏ việc mở kênh.'} },
  { type:'calc', stem:'Mục tiêu 5 đơn/ngày trong 60 ngày. Tỉ lệ chuyển đổi trang sản phẩm là 2%. Cần tổng cộng bao nhiêu lượt xem trang sản phẩm?',
    unit:'lượt', ans:15000, tol:1, wrong:[[6,'QUEN_TI_LE_CHUYEN_DOI'],[250,'QUEN_TI_LE_CHUYEN_DOI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Tổng đơn = 5 × 60 = 300 đơn.','Lượt xem = 300 ÷ 2% = <b>15.000 lượt</b>.'] },
  { type:'mcq', stem:'Một shop trà sữa đóng chai có ba bạn trẻ rất thích quay video, giá rẻ, sản phẩm dễ thể hiện trên màn hình. Nên thử sàn nào trước?',
    options:[{k:'a',t:'Sàn thiên khám phá bằng video, vì khớp đúng năng lực nhóm'},{k:'b',t:'Sàn thiên tìm kiếm, vì người mua trà sữa luôn gõ tìm theo tên hãng'},
             {k:'c',t:'Sàn có nhiều người dùng nhất, vì đông khách thì chắc chắn ra đơn'},{k:'d',t:'Website riêng, vì như vậy không phải chia phí cho bất kỳ sàn nào'}],
    answer:'a', why:{a:'Đúng. Nhóm có năng lực video và sản phẩm hợp màn hình; đây là lợi thế sàn khám phá thưởng.',
      b:'Thương hiệu mới chưa ai biết tên thì chưa ai gõ tìm tên hãng.',
      c:'Đông người dùng cũng đông đối thủ; con số đó không nói bạn thắng ở đâu.',
      d:'Website riêng không có dòng khách sẵn; shop mới sẽ phải tự trả tiền kéo từng lượt truy cập.'} },
  { type:'mcq', stem:'Sau 60 ngày chị Hà đạt 5 đơn/ngày ổn định trên sàn đầu. Bước hợp lý tiếp theo là gì?',
    options:[{k:'a',t:'Tăng gấp đôi ngân sách ở sàn cũ trước, sàn mới để sang năm'},{k:'b',t:'Đóng Facebook vì sàn đã ra đơn, tập trung hẳn một chỗ'},
             {k:'c',t:'Mở tiếp hai sàn còn lại cùng lúc cho kịp mùa cao điểm cuối năm'},{k:'d',t:'Thuê người làm video rồi thử sàn khám phá với ngân sách nhỏ'}],
    answer:'d', why:{a:'Có thể tăng dần, nhưng câu hỏi đặt ra là mở rộng kênh; chưa có dấu hiệu sàn cũ còn dư địa gấp đôi.',
      b:'Facebook đang có 150 đơn/tháng và là nơi giữ quan hệ trực tiếp với khách; bỏ là mất.',
      c:'Lặp lại đúng lỗi chia mỏng, chỉ là ở quy mô lớn hơn.',
      d:'Đúng. Bổ sung năng lực còn thiếu trước, rồi thử kênh mới ở quy mô nhỏ để đo.'} },
  { type:'mcq', stem:'Vì sao "sàn nào đông người dùng nhất" chưa phải lý do đủ để chọn sàn đầu tiên?',
    options:[{k:'a',t:'Vì con số người dùng do sàn tự công bố nên luôn luôn bị thổi phồng'},{k:'b',t:'Vì bạn chỉ thắng ở nơi năng lực của mình được thuật toán thưởng'},
             {k:'c',t:'Vì sàn đông người thì phí luôn cao hơn hẳn các sàn còn lại'},{k:'d',t:'Vì người dùng đông nhất thường là khách mua giá rẻ, ít lãi'}],
    answer:'b', why:{a:'Có thể có chênh lệch, nhưng kể cả số đúng thì vẫn thiếu phần năng lực của bạn.',
      b:'Đúng. Đông người mà nội dung/giá của bạn không khớp cách sàn phân phối thì vẫn không ra đơn.',
      c:'Phí không nhất thiết đi theo quy mô; đây không phải lý do cốt lõi.',
      d:'Khái quát quá; mỗi sàn có nhiều tệp khách khác nhau.'} },
  { type:'mcq', stem:'Dấu hiệu nào cho thấy shop đã sẵn sàng mở sàn thứ hai?',
    options:[{k:'a',t:'Có một ngày bán vượt 20 đơn nhờ một video lan truyền bất ngờ'},{k:'b',t:'Đối thủ chính vừa mở gian hàng ở sàn thứ hai tuần trước'},
             {k:'c',t:'Đơn đều ở sàn đầu, vận hành trơn, còn người và tiền dư'},{k:'d',t:'Sàn thứ hai đang có chương trình miễn phí cho shop mới đăng ký'}],
    answer:'c', why:{a:'Một ngày đột biến không phải nhịp đều; có thể không lặp lại.',
      b:'Đối thủ đi không có nghĩa bạn đã đủ lực để đi.',
      c:'Đúng. Mở rộng khi nền đã vững và còn nguồn lực, không phải khi có cớ.',
      d:'Ưu đãi giảm chi phí ban đầu, nhưng không tạo ra người vận hành hay nội dung.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kn03-02', skill:'measure', read:'7 phút', t:'Đơn 200.000đ trên sàn, bạn thật sự lãi bao nhiêu?',
  situation:'Shop túi vải của Minh bán một mẫu giá 200.000đ, giá vốn 90.000đ. Minh nghĩ mỗi đơn lãi 110.000đ. Cuối tháng, 600 đơn nhưng tiền về tài khoản ít hơn nhiều so với 66 triệu anh tính. Đơn nào cũng dùng voucher shop 20.000đ, và sàn trừ phí trước khi chuyển tiền.',
  concept:{ name:'Lãi đóng góp mỗi đơn trên sàn',
    body:'Giá niêm yết không phải tiền bạn nhận. Từ giá đó phải trừ: <b>voucher do shop chịu</b>, <b>phí sàn</b> (phí cố định/hoa hồng, tính theo phần trăm), <b>phí thanh toán</b>, rồi <b>giá vốn</b> và <b>đóng gói</b>. Phần còn lại là lãi đóng góp mỗi đơn — tiền để trả quảng cáo, lương và mặt bằng. Tỉ lệ phí trong bài này là minh hoạ; mỗi sàn và mỗi ngành có biểu phí riêng, thay đổi theo thời kỳ, nên luôn lấy từ trang quy định của sàn khi tính thật.' },
  example:'Giả định phí sàn 10% và phí thanh toán 4%, cùng tính trên số tiền khách trả. Khách trả 200.000 − 20.000 = 180.000đ. Phí: 14% × 180.000 = 25.200đ. Giá vốn 90.000đ, đóng gói 5.000đ. Lãi đóng góp = 180.000 − 25.200 − 90.000 − 5.000 = 59.800đ, chỉ bằng khoảng 54% con số 110.000đ Minh tưởng. 600 đơn cho 35,9 triệu, chưa trừ quảng cáo.',
  takeaway:'Lãi trên sàn tính từ tiền khách thật trả, sau voucher và mọi loại phí — không tính từ giá niêm yết.',
  apply:'Lấy một sản phẩm bạn bán. Viết một dòng: giá − voucher − phí sàn − phí thanh toán − giá vốn − đóng gói = ? rồi đọc to con số.',
  mistakes:['Tính phí trên giá niêm yết trong khi khách trả sau voucher.','Coi lãi đóng góp là lãi ròng, quên còn phải trả quảng cáo.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao tiền về tài khoản của Minh thấp hơn nhiều so với 110.000đ × 600 đơn?',
    options:[{k:'a',t:'Sàn giữ tiền lại vài tuần nên số dư cuối tháng chưa đủ'},{k:'b',t:'Có nhiều đơn bị hoàn nên doanh thu thực tế giảm mạnh'},
             {k:'c',t:'Minh tính sai giá vốn, thực tế giá vốn cao hơn 90.000đ'},{k:'d',t:'Voucher và các loại phí bị trừ trước khi tiền được chuyển về'}],
    answer:'d', why:{a:'Độ trễ đối soát có thể có, nhưng tình huống nói tiền "ít hơn" chứ không phải "chưa về".',
      b:'Hoàn đơn làm giảm thêm, nhưng tình huống đã chỉ ra voucher và phí trên mọi đơn.',
      c:'Không có dữ kiện nào nói giá vốn sai.',
      d:'Đúng. Voucher 20.000đ và phần trăm phí bị trừ trên mọi đơn, trước khi Minh nhận tiền.'} },
  { type:'mcq', stem:'Minh muốn chạy voucher 40.000đ thay vì 20.000đ để tăng đơn. Bạn đề xuất anh làm gì trước khi bật?',
    options:[{k:'a',t:'Bật ngay vì voucher lớn thì đơn tăng, lãi tổng chắc chắn tăng theo'},{k:'b',t:'Tính lại lãi mỗi đơn rồi tính số đơn phải tăng để hoà'},
             {k:'c',t:'Tăng giá niêm yết lên 220.000đ để khách thấy voucher lớn hơn'},{k:'d',t:'Chỉ bật voucher cho khách cũ vì họ đã quen sản phẩm'}],
    answer:'b', why:{a:'Voucher gấp đôi cắt thẳng vào lãi mỗi đơn; đơn tăng chưa chắc bù được.',
      b:'Đúng. Voucher 40.000đ làm lãi còn khoảng 42.600đ; cần biết phải bán thêm bao nhiêu mới giữ nguyên tổng lãi.',
      c:'Đẩy giá để giảm ảo có rủi ro với khách và quy định sàn; không trả lời câu hỏi lãi.',
      d:'Có thể là một phương án, nhưng chưa tính số thì chưa biết có đáng hay không.'} },
  { type:'calc', stem:'Giá 200.000đ, voucher shop 20.000đ, phí sàn 10% và phí thanh toán 4% tính trên tiền khách trả (minh hoạ), giá vốn 90.000đ, đóng gói 5.000đ. Lãi đóng góp mỗi đơn là bao nhiêu đồng?',
    unit:'đ', ans:59800, tol:10, wrong:[[57000,'SAI_MAU_SO'],[110000,'QUEN_CHI_PHI_BIEN_DOI'],[79800,'GIAM_GIA_QUEN_BIEN']], errors:['SAI_MAU_SO','QUEN_CHI_PHI_BIEN_DOI','GIAM_GIA_QUEN_BIEN'],
    steps:['Tiền khách trả = 200.000 − 20.000 = 180.000đ.','Phí = 14% × 180.000 = 25.200đ.','Lãi = 180.000 − 25.200 − 90.000 − 5.000 = <b>59.800đ</b>.'] },
  { type:'calc', stem:'Với voucher 40.000đ: khách trả 160.000đ, phí 14% (minh hoạ), giá vốn 90.000đ, đóng gói 5.000đ. Lãi mỗi đơn là bao nhiêu đồng?',
    unit:'đ', ans:42600, tol:10, wrong:[[39800,'SAI_MAU_SO'],[65000,'QUEN_CHI_PHI_BIEN_DOI']], errors:['SAI_MAU_SO','QUEN_CHI_PHI_BIEN_DOI'],
    steps:['Phí = 14% × 160.000 = 22.400đ.','Lãi = 160.000 − 22.400 − 90.000 − 5.000 = <b>42.600đ</b>.'] },
  { type:'calc', stem:'Hiện 600 đơn/tháng với lãi 59.800đ/đơn. Nếu voucher 40.000đ làm lãi còn 42.600đ/đơn, cần bao nhiêu đơn/tháng để giữ nguyên tổng lãi đóng góp? (làm tròn lên)',
    unit:'đơn', ans:843, tol:1, wrong:[[600,'GIAM_GIA_QUEN_BIEN'],[1200,'SAI_TINH_TOAN']], errors:['GIAM_GIA_QUEN_BIEN'],
    steps:['Tổng lãi hiện tại = 600 × 59.800 = 35.880.000đ.','Số đơn cần = 35.880.000 ÷ 42.600 ≈ 842,3 → <b>843 đơn</b> (tăng khoảng 40%).'] },
  { type:'mcq', stem:'Một shop tính: giá 150.000đ, giá vốn 60.000đ, "vậy biên lãi 60%". Lỗi chính trong cách nói này là gì?',
    options:[{k:'a',t:'Biên lãi phải tính trên giá vốn chứ không tính trên giá bán'},{k:'b',t:'Giá vốn thực tế trên sàn luôn cao hơn so với khi bán ở cửa hàng'},
             {k:'c',t:'Đó mới là biên gộp theo giá niêm yết, chưa trừ voucher và phí sàn'},{k:'d',t:'Biên 60% là quá cao, chắc chắn đã nhập sai giá vốn sản phẩm'}],
    answer:'c', why:{a:'Có nhiều cách tính biên; vấn đề ở đây không phải mẫu số mà là thiếu chi phí.',
      b:'Giá vốn hàng không đổi theo kênh; cái đổi là phí kênh.',
      c:'Đúng. Trên sàn còn voucher, phí phần trăm và đóng gói; biên thật thấp hơn nhiều.',
      d:'60% biên gộp là bình thường ở nhiều ngành; không có căn cứ nói nhập sai.'} },
  { type:'mcq', stem:'Vì sao nên tính phí phần trăm trên tiền khách trả sau voucher, không trên giá niêm yết (theo giả định của bài)?',
    options:[{k:'a',t:'Vì phần trăm phí tính trên giá trị giao dịch thực, không trên giá gạch'},{k:'b',t:'Vì như vậy con số phí nhỏ hơn, lãi đẹp hơn trong báo cáo gửi sếp'},
             {k:'c',t:'Vì sàn luôn miễn phí cho phần giá trị mà voucher của shop đã giảm'},{k:'d',t:'Vì giá niêm yết chỉ là con số tham khảo, không dùng để tính gì'}],
    answer:'a', why:{a:'Đúng theo giả định bài: phí đi theo số tiền giao dịch. Khi tính thật, kiểm tra cách tính trong quy định của sàn.',
      b:'Tính để đúng, không để đẹp.',
      c:'Khẳng định cụ thể về chính sách sàn không có căn cứ trong bài.',
      d:'Giá niêm yết vẫn là điểm xuất phát; chỉ không phải tiền khách trả.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kn03-03', skill:'channel', read:'7 phút', t:'Quảng cáo tìm kiếm trong sàn hay kéo khách từ Facebook vào sàn?',
  situation:'Shop giày chạy bộ của Tuấn có 20 triệu/tháng cho quảng cáo. Nhân viên đề xuất chạy quảng cáo Facebook dẫn link về gian hàng trên sàn vì "Facebook rẻ, 800đ một click". Quảng cáo tìm kiếm trong sàn cho từ khoá "giày chạy bộ nam" tốn khoảng 1.500đ một click. Tuấn không biết nên dồn tiền vào đâu.',
  concept:{ name:'Chi phí mỗi đơn, không phải chi phí mỗi click',
    body:'Click rẻ chưa chắc đơn rẻ. Người bấm từ khoá trong sàn đang ở tư thế mua: họ đã mở ứng dụng, gõ tên sản phẩm. Người bấm quảng cáo Facebook đang lướt, phải chuyển ứng dụng, đăng nhập, rồi mới xem. Vì vậy tỉ lệ chuyển đổi thường khác nhau nhiều. So hai kênh bằng <b>chi phí mỗi đơn = giá click ÷ tỉ lệ chuyển đổi</b>, rồi so với lãi đóng góp mỗi đơn. Quảng cáo ngoài sàn có vai trò riêng: tạo nhu cầu với người chưa tìm — nhưng phải được đo bằng thước đo phù hợp.' },
  example:'Giả sử click trong sàn 1.500đ, tỉ lệ chuyển đổi 3% → 50.000đ/đơn. Click Facebook 800đ, tỉ lệ chuyển đổi 0,8% → 100.000đ/đơn. Lãi đóng góp mỗi đôi giày là 120.000đ. Trong sàn còn lãi 70.000đ/đơn, Facebook chỉ còn 20.000đ. Với 20 triệu, Tuấn nên dồn phần lớn vào tìm kiếm trong sàn, giữ một phần nhỏ thử Facebook cho mẫu mới chưa ai biết để tìm.',
  takeaway:'So kênh bằng chi phí mỗi đơn đặt cạnh lãi mỗi đơn; giá click rẻ chỉ là nửa phép tính.',
  apply:'Lấy hai kênh quảng cáo bạn đang dùng. Nói trong 60 giây: giá click, tỉ lệ chuyển đổi, chi phí mỗi đơn của từng kênh.',
  mistakes:['Chọn kênh theo giá click rẻ nhất.','Tính hiệu quả Facebook bằng đơn cuối cùng trong khi vai trò của nó là tạo nhu cầu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: click Facebook 800đ, click trong sàn 1.500đ. Kênh nào nhiều khả năng cho đơn rẻ hơn?',
    options:[{k:'a',t:'Facebook, vì giá click chỉ bằng khoảng một nửa'},{k:'b',t:'Trong sàn, vì người bấm đang tìm đúng sản phẩm để mua'},
             {k:'c',t:'Hai kênh như nhau vì khách cuối cùng đều mua trên sàn'},{k:'d',t:'Facebook, vì tệp người dùng rộng hơn nên ra nhiều đơn hơn'}],
    answer:'b', why:{a:'Giá click chỉ là một vế; tỉ lệ chuyển đổi quyết định vế còn lại.',
      b:'Đúng. Ý định mua cao làm tỉ lệ chuyển đổi cao, thường bù được giá click đắt hơn.',
      c:'Nơi thanh toán giống nhau, nhưng hành trình đến đó khác nhau và rơi rụng khác nhau.',
      d:'Rộng hơn nghĩa là nhiều người chưa có nhu cầu, tỉ lệ mua thấp hơn.'} },
  { type:'mcq', stem:'Với số liệu minh hoạ trong bài, bạn chọn cách chia 20 triệu nào cho tháng tới?',
    options:[{k:'a',t:'Dồn hết vào Facebook vì click rẻ, được nhiều lượt truy cập hơn'},{k:'b',t:'Chia đôi 10/10 cho công bằng rồi xem kênh nào thắng'},
             {k:'c',t:'Dồn hết vào tìm kiếm trong sàn và tắt hẳn quảng cáo Facebook'},{k:'d',t:'Phần lớn cho tìm kiếm trong sàn, phần nhỏ thử Facebook cho mẫu mới'}],
    answer:'d', why:{a:'Nhiều truy cập nhưng mỗi đơn đắt gấp đôi, lãi còn rất mỏng.',
      b:'Đã có số để quyết; chia đều là bỏ qua dữ kiện.',
      c:'Tắt hẳn làm mất khả năng tạo nhu cầu cho mẫu chưa ai tìm.',
      d:'Đúng. Theo số, tiền đi về chỗ lãi cao; giữ một phần nhỏ cho vai trò Facebook làm tốt hơn.'} },
  { type:'calc', stem:'Click tìm kiếm trong sàn 1.500đ, tỉ lệ chuyển đổi 3%. Chi phí quảng cáo cho mỗi đơn là bao nhiêu đồng?',
    unit:'đ', ans:50000, tol:1, wrong:[[45,'QUEN_TI_LE_CHUYEN_DOI'],[500,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Chi phí mỗi đơn = giá click ÷ tỉ lệ chuyển đổi.','1.500 ÷ 0,03 = <b>50.000đ</b>.'] },
  { type:'calc', stem:'Lãi đóng góp mỗi đôi giày 120.000đ. Click Facebook 800đ, tỉ lệ chuyển đổi 0,8%. Sau khi trừ quảng cáo, mỗi đơn từ Facebook còn lãi bao nhiêu đồng?',
    unit:'đ', ans:20000, tol:1, wrong:[[120000,'QUEN_TRU_CHI_PHI_QC'],[119200,'QUEN_TI_LE_CHUYEN_DOI']], errors:['QUEN_TRU_CHI_PHI_QC','QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Chi phí mỗi đơn = 800 ÷ 0,008 = 100.000đ.','Lãi còn = 120.000 − 100.000 = <b>20.000đ</b>.'] },
  { type:'mcq', stem:'Báo cáo ghi ROAS quảng cáo trong sàn là 5. Tuấn nói "cứ 1 đồng quảng cáo lãi 5 đồng". Bạn sửa thế nào?',
    options:[{k:'a',t:'ROAS 5 là 5 đồng doanh thu, chưa trừ giá vốn, phí và voucher'},{k:'b',t:'ROAS 5 là 5 đồng lãi nhưng chưa trừ thuế thu nhập của shop'},
             {k:'c',t:'ROAS 5 là quá thấp, ngành giày phải đạt ít nhất từ 10 trở lên'},{k:'d',t:'ROAS 5 nghĩa là cứ 5 click thì được một đơn hàng thành công'}],
    answer:'a', why:{a:'Đúng. ROAS là doanh thu ÷ chi quảng cáo; lãi thật phải trừ tiếp mọi chi phí khác.',
      b:'ROAS không đo lãi ở bất kỳ tầng nào.',
      c:'Ngưỡng ROAS đủ hay thiếu phụ thuộc biên lãi của chính shop, không có con số chung cho ngành.',
      d:'Đó là tỉ lệ chuyển đổi, một chỉ số khác.'} },
  { type:'mcq', stem:'Shop ra mẫu giày thiết kế mới, chưa ai biết tên, từ khoá gần như không có người tìm. Vai trò hợp lý của quảng cáo ngoài sàn lúc này là gì?',
    options:[{k:'a',t:'Không nên dùng vì chi phí mỗi đơn luôn cao hơn trong sàn'},{k:'b',t:'Thay hẳn quảng cáo tìm kiếm vì từ khoá không đem lại gì'},
             {k:'c',t:'Tạo nhu cầu cho mẫu mới, đo thêm lượt tìm tên mẫu trên sàn'},{k:'d',t:'Chỉ dùng để tăng lượt theo dõi trang, không cần đo đơn'}],
    answer:'c', why:{a:'Với mẫu chưa ai tìm, tìm kiếm trong sàn không có nhu cầu để bắt; cần nơi tạo nhu cầu.',
      b:'Từ khoá chung ("giày chạy bộ") vẫn có người tìm; không cần bỏ.',
      c:'Đúng. Đo vai trò tạo nhu cầu bằng lượt tìm tên mẫu và đơn sau đó, không chỉ đơn trực tiếp.',
      d:'Lượt theo dõi không trả lương; vẫn phải nối về đơn hoặc lượt tìm.'} },
  { type:'mcq', stem:'Click trong sàn tăng từ 1.500đ lên 2.400đ do đối thủ đấu giá cùng từ khoá, tỉ lệ chuyển đổi vẫn 3%. Nhận định nào đúng?',
    options:[{k:'a',t:'Vẫn chạy vì ROAS trong sàn luôn tốt hơn Facebook dù giá tăng'},{k:'b',t:'Mỗi đơn tốn 80.000đ, lãi còn 40.000đ — vẫn còn lãi nhưng mỏng'},
             {k:'c',t:'Phải tắt ngay vì giá click đã đắt gấp ba lần giá Facebook'},{k:'d',t:'Tăng giá bán lên 30% để bù lại phần giá click đã tăng thêm'}],
    answer:'b', why:{a:'"Luôn" là sai; phải tính lại mỗi khi giá click đổi.',
      b:'Đúng. 2.400 ÷ 3% = 80.000đ; 120.000 − 80.000 = 40.000đ. Còn lãi nhưng cần theo dõi và tìm từ khoá dài ít cạnh tranh.',
      c:'So giá click giữa hai kênh lại lặp lỗi cũ; phải so chi phí mỗi đơn.',
      d:'Tăng giá mạnh làm giảm tỉ lệ chuyển đổi, có thể mất nhiều hơn được.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kn03-04', skill:'channel', read:'7 phút', t:'Vì sao sản phẩm của bạn nằm trang 5 khi khách tìm kiếm?',
  situation:'Shop bình giữ nhiệt của Lan có giá rẻ hơn đối thủ 10%, nhưng khi gõ "bình giữ nhiệt 500ml" thì sản phẩm nằm ở trang 5. Trang sản phẩm đặt tên "BÌNH HOT SALE SIÊU RẺ ĐẸP". Mỗi ngày có 400 lượt xem, 4 đơn. Đối thủ trang 1 có 600 lượt xem và 18 đơn mỗi ngày.',
  concept:{ name:'Liên quan và hiệu quả bán',
    body:'Mỗi sàn có thuật toán riêng và không công bố chi tiết, nhưng logic chung dễ đoán: sàn muốn hiển thị thứ khách <b>có khả năng mua nhất</b>, vì sàn thu phí trên đơn. Vì vậy thứ hạng thường dựa trên hai nhóm tín hiệu. <b>Liên quan</b>: tiêu đề, danh mục, thuộc tính khớp đúng từ khoá khách gõ. <b>Hiệu quả</b>: tỉ lệ bấm, tỉ lệ chuyển đổi, số đơn gần đây, đánh giá, giao đúng hạn. Giá rẻ chỉ giúp khi nó làm tăng các tín hiệu hiệu quả đó.' },
  example:'Tiêu đề của Lan không có chữ "500ml" hay "giữ nhiệt inox", nên khó khớp từ khoá. Tỉ lệ chuyển đổi 4 ÷ 400 = 1%, trong khi đối thủ 18 ÷ 600 = 3%. Sàn thấy đặt sản phẩm của Lan lên đầu sẽ bán ít hơn, nên đẩy đối thủ. Lan sửa tiêu đề thành "Bình giữ nhiệt inox 304 500ml giữ lạnh 12 giờ", thêm ảnh đo nhiệt độ, và nhắm tỉ lệ chuyển đổi 2% trước.',
  takeaway:'Sàn xếp hạng thứ nó tin là bán được; hãy khớp từ khoá và chứng minh bằng tỉ lệ chuyển đổi.',
  apply:'Mở trang sản phẩm chính của bạn. Nói trong 60 giây: tiêu đề có chứa đúng ba từ khoá khách hay gõ không, tỉ lệ chuyển đổi đang là bao nhiêu.',
  mistakes:['Nhồi chữ "hot, rẻ, sale" vào tiêu đề thay vì từ khoá mô tả.','Nghĩ cứ giảm giá là tự lên hạng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: sàn có động cơ gì khi quyết định sản phẩm nào đứng đầu kết quả tìm kiếm?',
    options:[{k:'a',t:'Ưu tiên sản phẩm giá rẻ nhất để khách hài lòng'},{k:'b',t:'Ưu tiên shop mở lâu năm vì đáng tin hơn shop mới'},
             {k:'c',t:'Đưa lên thứ có khả năng thành đơn cao nhất'},{k:'d',t:'Xoay vòng để shop nào cũng có lượt được hiển thị'}],
    answer:'c', why:{a:'Giá rẻ không bán được thì sàn cũng không thu được phí.',
      b:'Tuổi shop có thể là một tín hiệu nhỏ, không phải động cơ chính.',
      c:'Đúng. Sàn thu tiền trên đơn, nên đặt lên đầu thứ nhiều khả năng ra đơn.',
      d:'Xoay vòng đều làm giảm đơn; sàn không có lý do làm vậy.'} },
  { type:'mcq', stem:'Bạn là Lan, chỉ có một tuần. Bạn sửa gì trước?',
    options:[{k:'a',t:'Giảm thêm 10% để chắc chắn là rẻ nhất trong kết quả tìm kiếm'},{k:'b',t:'Sửa tiêu đề theo từ khoá thật, thêm ảnh chứng minh giữ nhiệt'},
             {k:'c',t:'Đổi tên shop cho dễ nhớ và mua thêm lượt theo dõi gian hàng'},{k:'d',t:'Đăng lại sản phẩm mới hoàn toàn để được tính là sản phẩm mới'}],
    answer:'b', why:{a:'Đã rẻ hơn 10% mà vẫn trang 5; vấn đề không nằm ở giá.',
      b:'Đúng. Sửa cả hai nhóm tín hiệu: khớp từ khoá và tăng tỉ lệ chuyển đổi.',
      c:'Theo dõi ảo không làm tăng đơn, còn có rủi ro vi phạm quy định.',
      d:'Mất hết đơn và đánh giá đã có; bắt đầu lại từ số 0.'} },
  { type:'calc', stem:'Sản phẩm của Lan có 400 lượt xem và 4 đơn mỗi ngày. Tỉ lệ chuyển đổi là bao nhiêu phần trăm?',
    unit:'%', ans:1, tol:0.01, wrong:[[100,'SAI_MAU_SO'],[10000,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ chuyển đổi = đơn ÷ lượt xem.','4 ÷ 400 = 0,01 = <b>1%</b>.'] },
  { type:'calc', stem:'Nếu Lan giữ 400 lượt xem/ngày và nâng tỉ lệ chuyển đổi từ 1% lên 2%, mỗi tháng 30 ngày có thêm bao nhiêu đơn?',
    unit:'đơn', ans:120, tol:0.5, wrong:[[4,'NHAM_SO_TUYET_DOI'],[240,'NHAM_SO_TUYET_DOI']], errors:['NHAM_SO_TUYET_DOI'],
    steps:['Đơn/ngày tăng từ 4 lên 8, thêm 4 đơn.','4 × 30 = <b>120 đơn</b>.'] },
  { type:'mcq', stem:'Một shop đặt tiêu đề "Áo thun nam nữ unisex form rộng cotton đẹp rẻ hot trend 2026 freeship". Vấn đề chính là gì?',
    options:[{k:'a',t:'Tiêu đề quá dài, sàn sẽ tự cắt bớt và phạt nặng shop'},{k:'b',t:'Có chữ "hot trend" dễ bị coi là quảng cáo sai sự thật'},
             {k:'c',t:'Chữ quảng cáo lấn chỗ thông tin khách thật sự dùng để tìm'},{k:'d',t:'Có cả "nam nữ" nên sàn không biết xếp vào danh mục nào'}],
    answer:'c', why:{a:'Độ dài có giới hạn tuỳ sàn; vấn đề là chữ nào đang chiếm chỗ.',
      b:'Không phải trọng tâm; không có căn cứ đó là vi phạm.',
      c:'Đúng. "đẹp rẻ hot trend freeship" ít ai gõ; nên thay bằng chất liệu, định lượng vải, kiểu dáng.',
      d:'Danh mục chọn riêng khi đăng; "unisex" là từ khoá hợp lệ.'} },
  { type:'mcq', stem:'Sau khi sửa, sản phẩm lên trang 2 nhưng tuần sau có 5 đánh giá 1 sao vì giao trễ. Điều gì có khả năng xảy ra với thứ hạng?',
    options:[{k:'a',t:'Tụt lại, vì giao trễ và đánh giá xấu làm giảm tín hiệu hiệu quả'},{k:'b',t:'Giữ nguyên, vì thứ hạng chỉ phụ thuộc tiêu đề và danh mục'},
             {k:'c',t:'Tăng lên, vì có thêm đánh giá là có thêm tương tác cho sản phẩm'},{k:'d',t:'Chỉ ảnh hưởng nếu khách viết đánh giá có chứa từ khoá tìm kiếm'}],
    answer:'a', why:{a:'Đúng. Đánh giá thấp làm tỉ lệ chuyển đổi giảm và giao trễ là tín hiệu vận hành xấu.',
      b:'Liên quan chỉ là một nửa; hiệu quả là nửa kia.',
      c:'Tương tác tiêu cực không làm sàn tin sản phẩm bán tốt hơn.',
      d:'Nội dung đánh giá có thể ảnh hưởng hiển thị, nhưng số sao và vận hành quan trọng hơn nhiều.'} },
  { type:'mcq', stem:'Vì sao "mua đơn ảo" để tăng lượt bán là nước đi tồi, ngoài chuyện vi phạm quy định sàn?',
    options:[{k:'a',t:'Vì chi phí mua đơn ảo thường đắt hơn chạy quảng cáo tìm kiếm'},{k:'b',t:'Vì khách thật nhìn số bán cao sẽ nghi ngờ và bỏ đi mua shop khác'},
             {k:'c',t:'Vì đơn ảo không có đánh giá nên không giúp gì cho thứ hạng'},{k:'d',t:'Vì kéo khách thật vào mà trang không bán được, chuyển đổi rơi'}],
    answer:'d', why:{a:'Có thể đúng hoặc không; không phải lý do cốt lõi.',
      b:'Phần lớn khách không nghi ngờ số bán; lý do chính nằm ở chỗ khác.',
      c:'Đơn ảo thường đi kèm đánh giá ảo; vấn đề không phải thiếu đánh giá.',
      d:'Đúng. Được đẩy lên nhưng trang không thuyết phục, tỉ lệ chuyển đổi thật thấp kéo hạng xuống lại.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kn03-05', skill:'creative', read:'7 phút', t:'Livestream bán hàng lần đầu: chuẩn bị gì để không nói chuyện một mình?',
  situation:'Shop đồ ăn vặt của Vy quyết định livestream tối thứ Sáu. Kế hoạch là "lên sóng 2 tiếng, giới thiệu hết 40 món, ai hỏi gì trả lời nấy". Buổi thử trước đó có 150 người vào nhưng lúc nào cũng chỉ 8–10 người ở lại, được 3 đơn. Vy nghĩ vấn đề là chưa đủ nổi tiếng.',
  concept:{ name:'Kịch bản phiên live',
    body:'Người xem vào ra liên tục; mỗi phút có người mới chưa nghe gì. Phiên live cần <b>kịch bản lặp theo vòng</b>, mỗi vòng 10–15 phút: móc câu (một ưu đãi chỉ có trong live), trình diễn một sản phẩm chủ lực, chứng minh (ăn thử, so sánh), kêu gọi mua có hạn giờ, rồi lặp. Chọn 3–5 món, không 40. Chuẩn bị trước: giá và mã giảm đã cài, người phụ trả lời bình luận, ánh sáng, âm thanh, và kho đủ hàng cho số đơn dự kiến.' },
  example:'Vy cắt 40 món còn 4 món chủ lực, mỗi vòng 12 phút: mở combo 99.000đ chỉ trong live, ăn thử khô gà trước camera, nhắc "còn 30 phút hết giá". Một bạn trả lời bình luận, ghim sản phẩm đang nói. Giả sử lượt vào vẫn 150 nhưng người ở lại tăng lên 25 và 20% người xem mua, phiên live có 30 đơn, gấp 10 lần buổi thử.',
  takeaway:'Live không phải buổi nói chuyện dài; đó là một vòng bán ngắn lặp lại cho người vừa vào.',
  apply:'Viết kịch bản một vòng 12 phút cho sản phẩm chủ lực của bạn: câu mở, cách chứng minh, câu chốt có hạn giờ.',
  mistakes:['Giới thiệu quá nhiều sản phẩm, người vào giữa chừng không bắt kịp.','Một người vừa nói vừa trả lời bình luận vừa chốt đơn.'],
  q:[
  { type:'mcq', stem:'Đoán trước: 150 người vào nhưng chỉ 8–10 người ở lại. Nguyên nhân nhiều khả năng nhất là gì?',
    options:[{k:'a',t:'Shop chưa đủ nổi tiếng nên người xem không có lý do tin tưởng'},{k:'b',t:'Người vào giữa chừng không hiểu đang bán gì, không có lý do ở lại'},
             {k:'c',t:'Giờ live tối thứ Sáu quá muộn, mọi người đã đi ngủ sớm'},{k:'d',t:'Sàn chưa đẩy phiên live nên người vào đều là người lạ'}],
    answer:'b', why:{a:'Người đã vào tức là đã có chút chú ý; giữ họ là việc của nội dung.',
      b:'Đúng. Không có móc câu lặp lại, người mới vào thấy một buổi nói chuyện dở dang và rời đi.',
      c:'Tối thứ Sáu thường không phải giờ muộn; và 150 lượt vào cho thấy vẫn có người xem.',
      d:'Người lạ vào là tốt; câu hỏi là vì sao họ không ở lại.'} },
  { type:'mcq', stem:'Bạn là Vy, chuẩn bị buổi live tới. Bạn chọn cách nào?',
    options:[{k:'a',t:'Thuê một KOL lớn dẫn live để có thật nhiều người xem ngay'},{k:'b',t:'Kéo dài buổi live lên 4 tiếng để giới thiệu đủ cả 40 món ăn vặt'},
             {k:'c',t:'4 món chủ lực, vòng 12 phút lặp lại, thêm người trả lời bình luận'},{k:'d',t:'Giảm giá tất cả 40 món 50% để người xem thấy hời mà ở lại'}],
    answer:'c', why:{a:'Có thể tăng lượt vào, nhưng kịch bản vẫn rời rạc thì người xem vẫn rời đi; lại tốn phí lớn.',
      b:'Dài hơn chỉ nhân lên vấn đề cũ.',
      c:'Đúng. Sửa thẳng vào lý do người xem rời đi, và chia việc để không ai quá tải.',
      d:'Giảm sâu toàn bộ đốt lãi, và 40 món vẫn quá nhiều để người xem theo dõi.'} },
  { type:'calc', stem:'Phiên live có 150 lượt vào, 20% mua, giá trị trung bình mỗi đơn 120.000đ. Doanh thu phiên live là bao nhiêu đồng?',
    unit:'đ', ans:3600000, tol:1, wrong:[[18000000,'QUEN_TI_LE_CHUYEN_DOI'],[360000,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Số đơn = 150 × 20% = 30 đơn.','Doanh thu = 30 × 120.000 = <b>3.600.000đ</b>.'] },
  { type:'mcq', stem:'Trong live, một người bình luận "khô gà có cay không, bé 5 tuổi ăn được không?". Người phụ nên làm gì?',
    options:[{k:'a',t:'Báo người dẫn trả lời ngay trên sóng và gợi ý vị không cay'},{k:'b',t:'Nhắn riêng cho khách sau khi kết thúc live để không làm gián đoạn'},
             {k:'c',t:'Bỏ qua vì người dẫn đang giữa vòng giới thiệu món chủ lực khác'},{k:'d',t:'Trả lời ngắn "có ạ" trong bình luận để giữ tốc độ phiên live'}],
    answer:'a', why:{a:'Đúng. Câu hỏi này nhiều người cùng thắc mắc; trả lời trên sóng chốt được cả nhóm phụ huynh đang xem.',
      b:'Sau live thì khách đã rời đi, ưu đãi đã hết.',
      c:'Câu hỏi mua hàng là tín hiệu nóng nhất; bỏ qua là bỏ đơn.',
      d:'"Có ạ" không trả lời được chuyện cay hay không, dễ dẫn đến đánh giá xấu.'} },
  { type:'mcq', stem:'Live được 80 đơn nhưng kho chỉ còn 50 gói combo, 30 đơn phải huỷ. Bài học chuẩn bị là gì?',
    options:[{k:'a',t:'Lần sau đặt giới hạn thấp hơn để khỏi bán quá nhiều đơn'},{k:'b',t:'Chốt tồn kho và cài số lượng suất trước giờ lên sóng'},
             {k:'c',t:'Huỷ đơn là chuyện bình thường, khách sẽ quay lại mua sau'},{k:'d',t:'Nên nói trên sóng là "hết hàng" chỉ khi có người hỏi'}],
    answer:'b', why:{a:'Bán được nhiều là tốt; cần khớp kho với đơn, không phải hạn chế bán.',
      b:'Đúng. Số suất cài đúng tồn kho vừa tránh huỷ vừa tạo cảm giác khan hiếm thật.',
      c:'Huỷ đơn do shop thường ảnh hưởng tỉ lệ vận hành và làm khách thất vọng.',
      d:'Đợi người hỏi thì đơn đã đặt; phải khoá số lượng từ đầu.'} },
  { type:'mcq', stem:'Vì sao ưu đãi "chỉ có trong live" quan trọng hơn giảm giá chung cho cả gian hàng?',
    options:[{k:'a',t:'Vì sàn tính phí thấp hơn cho đơn phát sinh trong phiên live'},{k:'b',t:'Vì giảm giá chung sẽ bị các đối thủ sao chép lại ngay lập tức'},
             {k:'c',t:'Vì nó cho người xem lý do mua ngay lúc đang xem, không để mai'},{k:'d',t:'Vì ưu đãi riêng giúp shop né được quy định về giá khuyến mãi'}],
    answer:'c', why:{a:'Không có căn cứ về chính sách phí như vậy trong bài.',
      b:'Đối thủ có thể sao chép cả hai; đó không phải điểm khác biệt.',
      c:'Đúng. Hạn giờ và độc quyền trong live biến sự quan tâm thành hành động ngay.',
      d:'Không phải mục đích, và né quy định là rủi ro chứ không phải lợi ích.'} },
  { type:'mcq', stem:'Sau ba phiên live, số người xem ổn định nhưng tỉ lệ mua giảm dần từ 20% xuống 8%. Bạn kiểm tra điều gì đầu tiên?',
    options:[{k:'a',t:'Người xem đã quen ưu đãi cũ và sản phẩm lặp lại mỗi phiên'},{k:'b',t:'Sàn đã giảm lượt đẩy phiên live của shop so với trước'},
             {k:'c',t:'Chất lượng camera kém đi làm hình ảnh món ăn kém hấp dẫn'},{k:'d',t:'Giờ phát sóng bị trùng với giờ phát sóng phim trên truyền hình'}],
    answer:'a', why:{a:'Đúng. Lượt xem giữ nguyên mà mua giảm thường do người xem quen, đã mua rồi, hoặc ưu đãi không còn mới.',
      b:'Người xem vẫn ổn định; vấn đề nằm ở bước mua, không ở lượt đẩy.',
      c:'Có thể, nhưng không có dữ kiện nào về camera thay đổi.',
      d:'Nếu vậy thì người xem giảm, không phải tỉ lệ mua giảm.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kn03-06', skill:'channel', read:'7 phút', t:'Có đáng trả thêm phí để vào gian hàng chính hãng (Mall)?',
  situation:'Thương hiệu serum nội địa của Khoa có giấy tờ đầy đủ và đang bán gian hàng thường, 1.000 đơn/tháng, giá 300.000đ. Nhân viên sàn mời vào gian hàng chính hãng: có nhãn chính hãng, được vào các chương trình riêng, nhưng phí trên đơn cao hơn. Theo giả định minh hoạ, phí tăng thêm 4 điểm phần trăm.',
  concept:{ name:'Tính điểm hoà khi đổi loại gian hàng',
    body:'Gian hàng chính hãng bán <b>niềm tin</b>: khách sợ hàng giả, nhất là mỹ phẩm, thực phẩm chức năng, đồ điện tử, sẽ mua dễ hơn khi thấy nhãn chính hãng. Bạn trả cho niềm tin đó bằng phí cao hơn và yêu cầu vận hành chặt hơn. Câu hỏi không phải "có tốt không", mà là "số đơn hoặc tỉ lệ chuyển đổi phải tăng bao nhiêu để bù phần phí tăng". Ngành càng nhạy với hàng giả, khả năng bù càng cao. Mức phí trong bài là minh hoạ; khi tính thật, lấy biểu phí hiện hành của sàn.' },
  example:'Mỗi đơn 300.000đ, lãi đóng góp hiện 120.000đ. Phí tăng 4 điểm phần trăm → thêm 12.000đ/đơn, lãi còn 108.000đ. Tổng lãi hiện tại 1.000 × 120.000 = 120 triệu. Để giữ nguyên, cần 120.000.000 ÷ 108.000 ≈ 1.112 đơn, tăng khoảng 11%. Với serum, khách rất sợ hàng giả; nếu nhãn chính hãng giúp tỉ lệ chuyển đổi tăng 20%, Khoa có lời. Nếu bán ốp lưng điện thoại giá rẻ, chuyện đó khó xảy ra.',
  takeaway:'Mall đáng khi phần đơn tăng thêm lớn hơn phần phí tăng thêm — tính điểm hoà trước, ký sau.',
  apply:'Nói trong 60 giây: khách ngành bạn sợ hàng giả đến mức nào, và bạn đoán nhãn chính hãng làm tăng chuyển đổi bao nhiêu phần trăm.',
  mistakes:['Vào Mall vì "trông chuyên nghiệp" mà không tính điểm hoà.','Nghĩ ngành nào cũng được lợi như nhau từ nhãn chính hãng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: ngành hàng nào nhiều khả năng được lợi nhất từ gian hàng chính hãng?',
    options:[{k:'a',t:'Móc khoá, sticker và phụ kiện trang trí giá dưới 30.000đ'},{k:'b',t:'Quần áo thời trang nhanh theo xu hướng, thay mẫu hằng tuần'},
             {k:'c',t:'Dụng cụ nhà bếp bằng nhựa, dễ thay thế, giá phổ thông'},{k:'d',t:'Mỹ phẩm, nơi khách sợ hàng giả ảnh hưởng đến da'}],
    answer:'d', why:{a:'Giá thấp, rủi ro mua nhầm hàng giả không đáng lo; nhãn chính hãng ít tác dụng.',
      b:'Thời trang nhanh cạnh tranh bằng mẫu và giá; ít người lo hàng giả.',
      c:'Rủi ro hàng kém chất lượng thấp, hậu quả nhỏ; ít cần bảo chứng.',
      d:'Đúng. Hậu quả hàng giả lớn làm khách sẵn sàng trả vì niềm tin.'} },
  { type:'mcq', stem:'Khoa hỏi bạn có nên ký không. Bạn chọn cách trả lời nào?',
    options:[{k:'a',t:'Ký ngay, vì thương hiệu nào lớn cũng có gian hàng chính hãng cả'},{k:'b',t:'Tính điểm hoà ~11% đơn tăng, so với mức tăng chuyển đổi dự kiến'},
             {k:'c',t:'Từ chối, vì phí cao hơn thì chắc chắn lãi thấp hơn hiện tại'},{k:'d',t:'Ký thử một tháng rồi xem doanh thu có tăng hay không là đủ'}],
    answer:'b', why:{a:'Bắt chước thương hiệu lớn mà bỏ qua con số của chính mình.',
      b:'Đúng. Biết ngưỡng cần vượt rồi mới đánh giá được khả năng vượt.',
      c:'Phí cao hơn chỉ làm lãi thấp hơn nếu đơn không tăng đủ.',
      d:'Nhìn doanh thu mà không có ngưỡng thì không biết tăng bao nhiêu là đủ.'} },
  { type:'calc', stem:'Giá 300.000đ, phí tăng thêm 4 điểm phần trăm (minh hoạ). Lãi mỗi đơn giảm bao nhiêu đồng?',
    unit:'đ', ans:12000, tol:1, wrong:[[4,'NHAM_DIEM_PHAN_TRAM'],[4800,'SAI_MAU_SO']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Phí tăng thêm = 4% × 300.000.','= <b>12.000đ</b> mỗi đơn.'] },
  { type:'calc', stem:'Hiện 1.000 đơn/tháng, lãi 120.000đ/đơn. Vào Mall lãi còn 108.000đ/đơn. Cần tối thiểu bao nhiêu đơn/tháng để giữ nguyên tổng lãi? (làm tròn lên)',
    unit:'đơn', ans:1112, tol:1, wrong:[[1040,'NHAM_DIEM_PHAN_TRAM'],[1100,'SAI_TINH_TOAN']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Tổng lãi hiện tại = 1.000 × 120.000 = 120.000.000đ.','Số đơn = 120.000.000 ÷ 108.000 ≈ 1.111,1 → <b>1.112 đơn</b>.'] },
  { type:'mcq', stem:'Sau 2 tháng ở Mall, đơn tăng 25% nhưng tỉ lệ hoàn vì "hàng không đúng mô tả" cũng tăng. Nhận định nào hợp lý?',
    options:[{k:'a',t:'Khách Mall kỳ vọng cao hơn; cần sửa mô tả cho khớp thật'},{k:'b',t:'Khách Mall khó tính vô lý, nên chấp nhận tỉ lệ hoàn cao hơn'},
             {k:'c',t:'Nên quay lại gian hàng thường vì khách ở đó dễ tính hơn'},{k:'d',t:'Tăng hoàn là do sàn xử lý khiếu nại nghiêng về phía khách'}],
    answer:'a', why:{a:'Đúng. Nhãn chính hãng nâng kỳ vọng; khoảng cách giữa mô tả và thực tế lộ rõ hơn.',
      b:'Gọi khách là "vô lý" bỏ qua tín hiệu sửa sản phẩm và trang bán.',
      c:'Đơn tăng 25% đã vượt điểm hoà 11%; vấn đề hoàn sửa được.',
      d:'Có thể có, nhưng lý do hoàn cụ thể là "không đúng mô tả" — nằm trong tầm shop sửa.'} },
  { type:'mcq', stem:'Một shop ốp lưng điện thoại giá 49.000đ muốn vào Mall "cho sang". Bạn góp ý gì?',
    options:[{k:'a',t:'Nên vào, vì nhãn chính hãng đẹp và sẽ thu hút nhiều khách hơn'},{k:'b',t:'Nên vào để được tham gia mọi chương trình ngày đôi của sàn'},
             {k:'c',t:'Khách ít sợ hàng giả ở ngành này; khó bù phí nên cân nhắc kỹ'},{k:'d',t:'Chỉ vào khi đã có đủ 10.000 đơn/tháng để được sàn giảm phí'}],
    answer:'c', why:{a:'"Đẹp" không phải lý do tài chính; khách mua ốp lưng quan tâm mẫu và giá.',
      b:'Được vào chương trình là một lợi ích, nhưng vẫn phải tính có bù phí không.',
      c:'Đúng. Niềm tin không phải rào cản mua ở ngành này, nên phần phí tăng khó được bù.',
      d:'Con số và chính sách này không có căn cứ trong bài.'} },
  { type:'mcq', stem:'Điểm hoà 11% đơn tăng thêm. Dữ kiện nào giúp bạn đoán tốt nhất liệu có đạt không, trước khi ký?',
    options:[{k:'a',t:'Tỉ lệ khách hỏi "có phải hàng thật không" trong tin nhắn và đánh giá'},{k:'b',t:'Số lượng đối thủ đã có gian hàng chính hãng trong cùng ngành serum'},
             {k:'c',t:'Tổng số người theo dõi gian hàng hiện tại của thương hiệu Khoa'},{k:'d',t:'Doanh thu năm ngoái của cả ngành serum trên toàn bộ sàn'}],
    answer:'a', why:{a:'Đúng. Đây là bằng chứng trực tiếp rằng nỗi lo hàng giả đang cản khách của chính shop.',
      b:'Cho biết cạnh tranh, không cho biết khách của bạn có đổi hành vi không.',
      c:'Người theo dõi đã tin shop; câu hỏi là người chưa mua.',
      d:'Quá rộng, không nói gì về tác động của nhãn lên shop bạn.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kn03-07', skill:'measure', read:'7 phút', t:'100 đơn đặt, bao nhiêu đơn thật sự thành tiền?',
  situation:'Shop phụ kiện tóc của Thảo nhận 1.000 đơn/tháng, 70% thanh toán khi nhận hàng. Cuối tháng Thảo thấy 12% đơn bị khách huỷ trước khi gửi, 8% đơn giao thất bại bị hoàn về. Mỗi đơn hoàn tốn phí vận chuyển hai chiều và đôi khi hàng móp phải bán rẻ. Thảo vẫn báo cáo "1.000 đơn".',
  concept:{ name:'Đơn thành công và chi phí đơn hỏng',
    body:'Đơn đặt không phải đơn thành tiền. Có hai kiểu rơi: <b>huỷ</b> trước khi gửi (mất công xử lý, gần như không mất tiền vận chuyển) và <b>hoàn</b> sau khi gửi (mất phí ship đi, ship về, đóng gói, có khi hỏng hàng). Hoàn tốn hơn huỷ nhiều. Hãy báo cáo theo đơn thành công, và tính lãi trên đơn thành công sau khi trừ chi phí đơn hoàn. Nguyên nhân hay gặp: khách đặt bốc đồng khi thanh toán lúc nhận, mô tả sai kỳ vọng, giao quá lâu.' },
  example:'1.000 đơn: huỷ 120, hoàn 80, thành công 800. Lãi đóng góp mỗi đơn thành công 40.000đ → 32 triệu. Mỗi đơn hoàn tốn 35.000đ (ship hai chiều, bao bì, hao hụt, số minh hoạ) → 2,8 triệu. Lãi thật 29,2 triệu, không phải 40 triệu Thảo nghĩ từ 1.000 đơn. Nếu gọi xác nhận đơn thanh toán khi nhận trên 200.000đ và sửa ảnh kích thước, hoàn giảm còn 4% thì tiết kiệm 1,4 triệu và có thêm 40 đơn thành công.',
  takeaway:'Đếm đơn thành công, không đếm đơn đặt; mỗi đơn hoàn là một khoản lỗ, không phải con số trung tính.',
  apply:'Lấy số tháng trước: đơn đặt, huỷ, hoàn, thành công. Nói trong 60 giây lý do hoàn lớn nhất là gì.',
  mistakes:['Báo cáo đơn đặt như đơn bán được.','Coi hoàn và huỷ tốn như nhau.'],
  q:[
  { type:'mcq', stem:'Đoán trước: loại đơn nào gây tốn kém hơn cho shop?',
    options:[{k:'a',t:'Đơn huỷ, vì khách huỷ nghĩa là shop mất khách hàng đó mãi mãi'},{k:'b',t:'Đơn hoàn, vì đã tốn ship đi, ship về và có thể hỏng hàng'},
             {k:'c',t:'Hai loại tốn như nhau vì cuối cùng đều không có doanh thu'},{k:'d',t:'Đơn huỷ, vì sàn phạt shop nặng hơn khi khách chủ động huỷ'}],
    answer:'b', why:{a:'Khách huỷ có thể quay lại; và chi phí trực tiếp của huỷ thấp.',
      b:'Đúng. Hoàn là đơn đã đi hết đường vận chuyển rồi quay về, mang theo đủ loại chi phí.',
      c:'Doanh thu như nhau (bằng 0), nhưng chi phí khác nhau nhiều.',
      d:'Khách huỷ thường không phải lỗi shop; không có căn cứ về mức phạt như vậy.'} },
  { type:'mcq', stem:'Thảo muốn giảm hoàn. Bạn chọn làm gì trước?',
    options:[{k:'a',t:'Bỏ hẳn thanh toán khi nhận để khỏi bị bom hàng lần nào nữa'},{k:'b',t:'Chặn tất cả khách từng hoàn đơn, kể cả khi họ hoàn vì lỗi shop'},
             {k:'c',t:'Tặng thêm quà trong mọi đơn để khách không nỡ trả hàng về'},{k:'d',t:'Gọi xác nhận đơn thanh toán khi nhận giá trị cao, sửa ảnh kích thước'}],
    answer:'d', why:{a:'70% đơn là thanh toán khi nhận; bỏ là mất phần lớn khách.',
      b:'Phạt cả khách hoàn vì lỗi shop; gốc rễ vẫn còn.',
      c:'Tốn chi phí trên mọi đơn trong khi chỉ 8% hoàn.',
      d:'Đúng. Nhắm vào hai nguyên nhân: đặt bốc đồng và mô tả sai kỳ vọng.'} },
  { type:'calc', stem:'1.000 đơn đặt, huỷ 12%, hoàn 8%. Lãi 40.000đ mỗi đơn thành công, mỗi đơn hoàn tốn 35.000đ. Lãi thật cả tháng là bao nhiêu đồng?',
    unit:'đ', ans:29200000, tol:1000, wrong:[[40000000,'SAI_MAU_SO'],[32000000,'QUEN_CHI_PHI_BIEN_DOI']], errors:['SAI_MAU_SO','QUEN_CHI_PHI_BIEN_DOI'],
    steps:['Thành công = 1.000 − 120 − 80 = 800 đơn → 800 × 40.000 = 32.000.000đ.','Chi phí hoàn = 80 × 35.000 = 2.800.000đ.','Lãi thật = 32.000.000 − 2.800.000 = <b>29.200.000đ</b>.'] },
  { type:'calc', stem:'Hoàn giảm từ 8% xuống 4% trên 1.000 đơn, huỷ giữ 12%. Có thêm bao nhiêu đơn thành công?',
    unit:'đơn', ans:40, tol:0.5, wrong:[[4,'NHAM_DIEM_PHAN_TRAM'],[50,'NHAM_DIEM_PHAN_TRAM']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Hoàn giảm 4 điểm phần trăm × 1.000 = 40 đơn.','Số đơn đó thành đơn thành công: thêm <b>40 đơn</b>.'] },
  { type:'mcq', stem:'Hai shop cùng 1.000 đơn đặt. Shop A hoàn 3%, shop B hoàn 15%. Ngoài lãi, điều gì khác nhiều khả năng bị ảnh hưởng ở shop B?',
    options:[{k:'a',t:'Chỉ số vận hành và thứ hạng tìm kiếm trên sàn có thể giảm'},{k:'b',t:'Shop B sẽ được sàn hỗ trợ phí vận chuyển nhiều hơn shop A'},
             {k:'c',t:'Khách của shop B trung thành hơn vì họ đã thử nhiều lần'},{k:'d',t:'Shop B được ưu tiên trong các chương trình giảm giá của sàn'}],
    answer:'a', why:{a:'Đúng. Tỉ lệ giao thành công là một tín hiệu vận hành sàn thường theo dõi.',
      b:'Không có lý do sàn thưởng cho tỉ lệ hoàn cao.',
      c:'Hoàn nhiều là trải nghiệm hỏng, không phải trung thành.',
      d:'Chương trình thường ưu tiên shop vận hành tốt, không phải ngược lại.'} },
  { type:'mcq', stem:'Lý do hoàn phổ biến nhất của Thảo là "kẹp tóc nhỏ hơn tưởng tượng". Sửa ở đâu hiệu quả nhất?',
    options:[{k:'a',t:'Giảm giá để khách bớt kỳ vọng vào sản phẩm khi nhận hàng'},{k:'b',t:'Đổi sang đơn vị vận chuyển khác có tốc độ giao nhanh hơn'},
             {k:'c',t:'Viết thêm chữ "nhỏ" in hoa vào tiêu đề sản phẩm trên sàn'},{k:'d',t:'Ảnh sản phẩm đặt cạnh bàn tay hoặc thước đo kích thước thật'}],
    answer:'d', why:{a:'Giá thấp không sửa được chuyện hình dung sai kích thước.',
      b:'Tốc độ giao không liên quan đến lý do "nhỏ hơn tưởng tượng".',
      c:'Chữ "nhỏ" mơ hồ và làm xấu tiêu đề; ảnh có vật so sánh rõ hơn nhiều.',
      d:'Đúng. Sửa đúng chỗ tạo ra kỳ vọng sai: hình ảnh không cho thấy kích thước.'} },
  { type:'mcq', stem:'Sếp hỏi "tháng này bán bao nhiêu đơn?". Báo cáo nào đúng tinh thần bài?',
    options:[{k:'a',t:'1.000 đơn, vì đó là số khách đã bấm đặt hàng trong tháng'},{k:'b',t:'880 đơn, vì chỉ trừ số đơn huỷ còn đơn hoàn vẫn đã gửi đi'},
             {k:'c',t:'800 đơn thành công, kèm 120 huỷ và 80 hoàn cùng lý do'},{k:'d',t:'1.000 đơn, và ghi chú riêng rằng có một ít đơn hoàn về'}],
    answer:'c', why:{a:'Đơn đặt không phải đơn thành tiền.',
      b:'Đơn hoàn không thành tiền và còn tốn thêm phí.',
      c:'Đúng. Con số thật cộng với bức tranh rơi rụng để sếp biết sửa ở đâu.',
      d:'"Một ít" giấu đi 20% đơn không thành tiền.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kn03-08', skill:'channel', read:'6 phút', t:'5.000 khách đã mua trên sàn: họ là khách của bạn hay của sàn?',
  situation:'Shop trà thảo mộc của Phong có 5.000 khách mua trên sàn trong năm qua. Phong muốn gửi tin chào mẫu mới cho họ nhưng nhận ra mình không có số điện thoại hay email ai cả. Tỉ lệ mua lại trên sàn chỉ 10%: phần lớn khách lần sau gõ "trà thảo mộc" và mua shop khác đang đứng đầu.',
  concept:{ name:'Khách thuê và khách sở hữu',
    body:'Trên sàn, bạn <b>thuê</b> quyền tiếp cận khách: sàn giữ dữ liệu, quyết định ai thấy bạn, và lần mua sau khách lại đi qua ô tìm kiếm nơi đối thủ đang chờ. Kênh bạn <b>sở hữu</b> (Zalo OA, danh sách khách qua thẻ bảo hành, cộng đồng thương hiệu) cho phép nói chuyện trực tiếp. Mỗi sàn có quy định riêng về việc dẫn khách ra ngoài — phải đọc kỹ và làm đúng. Trong phạm vi được phép, dùng công cụ giữ chân của chính sàn (theo dõi shop, voucher cho người theo dõi) và làm thương hiệu đủ mạnh để khách gõ tên bạn thay vì tên ngành.' },
  example:'5.000 khách, tỉ lệ mua lại 10% → 500 người quay lại. Phong khuyến khích theo dõi shop bằng voucher 15.000đ cho người theo dõi, gửi thông báo khi có mẫu mới, in tên thương hiệu nổi bật trên hộp. Mục tiêu: khách gõ "trà [tên thương hiệu]" thay vì "trà thảo mộc". Nếu mua lại lên 18%, Phong có thêm 400 đơn/năm mà không trả tiền từ khoá.',
  takeaway:'Sàn cho bạn mượn khách; việc của bạn là để lần sau khách gõ tên bạn chứ không gõ tên ngành.',
  apply:'Nói trong 60 giây: khách mua lần hai của bạn tìm đến bằng cách nào, và bạn có chủ động được cách đó không.',
  mistakes:['Tưởng số khách trên sàn là tài sản dữ liệu của mình.','Dẫn khách ra ngoài theo cách vi phạm quy định của sàn.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao tỉ lệ mua lại trên sàn của Phong chỉ 10%?',
    options:[{k:'a',t:'Trà của Phong kém nên khách không muốn mua thêm'},{k:'b',t:'Lần sau khách tìm tên ngành và thấy shop khác trước'},
             {k:'c',t:'Khách trên sàn chỉ mua một lần rồi bỏ ứng dụng hẳn'},{k:'d',t:'Sàn chặn không cho khách mua lại cùng một shop nhiều lần'}],
    answer:'b', why:{a:'Không có dữ kiện về chất lượng; nguyên nhân được nêu trong tình huống là cách khách tìm.',
      b:'Đúng. Khách nhớ ngành, không nhớ tên shop; mỗi lần mua lại là một cuộc đấu từ khoá mới.',
      c:'Khách vẫn mua trên sàn, chỉ là mua shop khác.',
      d:'Không có cơ chế như vậy.'} },
  { type:'mcq', stem:'Bạn là Phong. Bạn chọn làm gì để tăng mua lại, trong khuôn khổ quy định của sàn?',
    options:[{k:'a',t:'Nhắn tin riêng xin số điện thoại từng khách để chuyển qua Zalo'},{k:'b',t:'Mua thêm quảng cáo từ khoá "trà thảo mộc" để luôn đứng đầu'},
             {k:'c',t:'Voucher cho người theo dõi shop và in đậm tên thương hiệu trên hộp'},{k:'d',t:'Giảm giá sâu để khách nhớ shop là nơi rẻ nhất trong ngành'}],
    answer:'c', why:{a:'Có thể vi phạm quy định sàn về dẫn khách ra ngoài; phải kiểm tra kỹ trước.',
      b:'Làm vậy là trả tiền lại cho chính khách cũ mỗi lần họ mua.',
      c:'Đúng. Dùng công cụ sàn cho phép và xây trí nhớ thương hiệu để khách gõ tên bạn.',
      d:'Khách nhớ "rẻ" thì sẽ đi theo shop rẻ hơn bạn.'} },
  { type:'calc', stem:'5.000 khách, tỉ lệ mua lại tăng từ 10% lên 18%. Có thêm bao nhiêu khách mua lại mỗi năm?',
    unit:'khách', ans:400, tol:0.5, wrong:[[8,'NHAM_DIEM_PHAN_TRAM'],[900,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM','NHAM_SO_TUYET_DOI'],
    steps:['Tăng 8 điểm phần trăm.','5.000 × 8% = <b>400 khách</b>.'] },
  { type:'mcq', stem:'Dấu hiệu nào cho thấy thương hiệu đang chuyển từ "khách thuê" sang "khách nhớ tên"?',
    options:[{k:'a',t:'Lượt theo dõi gian hàng tăng mạnh sau đợt mua quảng cáo'},{k:'b',t:'Doanh thu tháng này cao hơn tháng trước khoảng 20% nhờ voucher'},
             {k:'c',t:'Số người tìm theo tên thương hiệu trên sàn tăng dần'},{k:'d',t:'Tỉ lệ bấm vào quảng cáo từ khoá chung của ngành tăng'}],
    answer:'c', why:{a:'Theo dõi có thể đến từ khuyến mãi, chưa chắc là nhớ tên.',
      b:'Doanh thu tăng có nhiều nguyên nhân, không riêng gì nhận biết thương hiệu.',
      c:'Đúng. Gõ tên bạn là bằng chứng khách chủ động tìm bạn, không qua cuộc đấu từ khoá chung.',
      d:'Đây vẫn là khách tìm tên ngành.'} },
  { type:'mcq', stem:'Một bạn đề xuất nhét tờ rơi "Kết bạn Zalo shop để nhận giá rẻ hơn trên sàn" vào mọi đơn. Bạn phản hồi gì?',
    options:[{k:'a',t:'Làm ngay vì đó là cách nhanh nhất để có dữ liệu riêng của khách'},{k:'b',t:'Làm nhưng chỉ nhét vào đơn giá trị cao để đỡ tốn chi phí in'},
             {k:'c',t:'Đổi thành "giá rẻ hơn 50%" để khách chắc chắn sẽ kết bạn'},{k:'d',t:'Kiểm tra quy định sàn trước; mời mua ngoài giá rẻ hơn rất rủi ro'}],
    answer:'d', why:{a:'Nhanh nhưng có thể vi phạm quy định, rủi ro bị xử lý gian hàng.',
      b:'Giảm số tờ không giảm rủi ro vi phạm.',
      c:'Làm rủi ro lớn hơn và phá giá chính kênh sàn.',
      d:'Đúng. Mỗi sàn có quy định riêng; lôi kéo khách mua ngoài bằng giá thường là vùng rủi ro nhất.'} },
  { type:'mcq', stem:'Vì sao phụ thuộc hoàn toàn vào một sàn là rủi ro về lâu dài?',
    options:[{k:'a',t:'Vì sàn có thể đổi phí, thuật toán, chính sách bất cứ lúc nào'},{k:'b',t:'Vì khách trên sàn luôn mua ít hơn khách ở các kênh khác'},
             {k:'c',t:'Vì sàn thường ưu tiên các thương hiệu nước ngoài hơn nội địa'},{k:'d',t:'Vì quảng cáo trên sàn luôn đắt hơn quảng cáo mạng xã hội'}],
    answer:'a', why:{a:'Đúng. Bạn không kiểm soát luật chơi; một thay đổi có thể cắt nửa doanh thu.',
      b:'Không có căn cứ; giá trị đơn tuỳ ngành và shop.',
      c:'Khẳng định không có căn cứ.',
      d:'Không "luôn"; phải so bằng chi phí mỗi đơn.'} },
  { type:'mcq', stem:'Shop mẹ và bé có 20.000 khách trên sàn, sản phẩm mua lặp lại mỗi tháng (tã, khăn ướt). Ưu tiên giữ chân nào hợp lý nhất?',
    options:[{k:'a',t:'Chạy quảng cáo ngoài sàn nhắm lại toàn bộ người đã từng xem'},{k:'b',t:'Gói mua định kỳ hoặc combo tháng, nhắc bằng công cụ của sàn'},
             {k:'c',t:'Giảm giá sâu mỗi đầu tháng để khách nhớ mà quay lại mua'},{k:'d',t:'Mở thêm một sàn khác để tiếp cận thêm khách mẹ và bé mới'}],
    answer:'b', why:{a:'Nhắm lại có thể giúp, nhưng tốn tiền trên mỗi lần; giữ chân tự nhiên rẻ hơn.',
      b:'Đúng. Nhu cầu lặp lại đều đặn; gói định kỳ khoá lần mua sau trước khi khách đi tìm.',
      c:'Dạy khách chỉ mua khi có giảm giá, bào lãi mỗi tháng.',
      d:'Đó là tìm khách mới, không phải giữ khách cũ.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:kn03-09', skill:'channel', read:'7 phút', t:'Giá trên sàn rẻ hơn đại lý: bạn đang tự đánh nhau với ai?',
  situation:'Hãng nước mắm của Quân bán qua 60 đại lý tạp hoá với giá lẻ khuyến nghị 85.000đ/chai. Trên sàn, để đua hạng, shop chính hãng chạy voucher cho giá cuối còn 68.000đ. Hai tháng sau, 15 đại lý gọi phàn nàn khách chê đắt, "trên mạng có 68 nghìn", và bắt đầu nhập ít đi.',
  concept:{ name:'Kỷ luật giá giữa các kênh',
    body:'Khi một sản phẩm bán ở nhiều kênh, khách so giá chỉ trong vài giây. Nếu kênh của chính hãng rẻ hơn hẳn kênh đối tác, bạn đang <b>ăn thịt kênh của mình</b>: đại lý mất khách, nhập ít đi, hàng biến mất khỏi kệ. Chênh lệch nhỏ giải thích được (phí ship, mua số lượng) thì chấp nhận được; chênh lớn thì không. Cách giữ kỷ luật: đặt giá sàn thấp nhất, khác biệt hoá bằng <b>quy cách</b> (combo 3 chai, dung tích lớn chỉ bán online) thay vì bằng giá cùng một chai.' },
  example:'Một chai trên sàn 68.000đ, ở đại lý 85.000đ: chênh 17.000đ, khoảng 20% giá đại lý. Quân chuyển sang bán combo 3 chai giá 229.000đ chỉ trên sàn — mỗi chai khoảng 76.333đ, rẻ hơn khoảng 10% vì mua số lượng, không đụng thẳng giá lẻ một chai. Chai lẻ trên sàn về 85.000đ, bằng giá khuyến nghị. Đại lý giữ được vai trò mua lẻ tiện, sàn giữ vai trò mua trữ.',
  takeaway:'Khác biệt giữa các kênh bằng quy cách và lý do, không bằng việc tự phá giá chính sản phẩm.',
  apply:'Nói trong 60 giây: sản phẩm chủ lực của bạn đang có giá ở từng kênh là bao nhiêu, chênh lệch nào khách có thể nhìn ra.',
  mistakes:['Phá giá trên sàn để đua hạng mà không nghĩ đến đại lý.','Tưởng khách không so giá giữa online và tạp hoá.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì dễ xảy ra khi giá sàn của chính hãng rẻ hơn đại lý 20%?',
    options:[{k:'a',t:'Đại lý tự tăng khuyến mãi để giữ khách, hãng không cần lo'},{k:'b',t:'Khách chuyển hết sang sàn nên hãng bán được nhiều hơn trước'},
             {k:'c',t:'Đại lý nhập ít đi, hàng dần biến mất khỏi kệ tạp hoá'},{k:'d',t:'Không ai để ý vì khách tạp hoá và khách sàn là hai nhóm tách biệt'}],
    answer:'c', why:{a:'Đại lý có biên lãi mỏng, khó tự giảm; phản ứng thường là nhập ít đi.',
      b:'Nhiều khách tạp hoá mua tiện ngay lúc cần, không chờ ship; mất kệ là mất nhóm này.',
      c:'Đúng. Đại lý bị khách chê đắt thì ưu tiên hãng khác dễ bán hơn.',
      d:'Tình huống cho thấy khách tạp hoá đã so với giá trên mạng.'} },
  { type:'mcq', stem:'Bạn là Quân. Bạn sửa chính sách giá thế nào?',
    options:[{k:'a',t:'Giảm giá lẻ khuyến nghị ở đại lý xuống 68.000đ cho đồng đều'},{k:'b',t:'Chai lẻ trên sàn về giá khuyến nghị, bán combo 3 chai riêng'},
             {k:'c',t:'Ngừng bán trên sàn để bảo vệ toàn bộ hệ thống đại lý hiện có'},{k:'d',t:'Giữ giá sàn 68.000đ vì doanh số sàn đang tăng tốt, đại lý tự lo'}],
    answer:'b', why:{a:'Đại lý mất biên lãi, có thể lỗ; và lãi của hãng cũng giảm trên mọi kênh.',
      b:'Đúng. Giữ giá lẻ đồng nhất, khác biệt bằng quy cách mua số lượng có lý do rõ.',
      c:'Mất một kênh đang tăng trưởng; vấn đề là giá, không phải việc có mặt.',
      d:'Đổi đơn sàn lấy mất 60 đại lý là đổi lỗ.'} },
  { type:'calc', stem:'Combo 3 chai giá 229.000đ. Giá mỗi chai trong combo rẻ hơn giá lẻ 85.000đ bao nhiêu phần trăm? (làm tròn 1 chữ số)',
    unit:'%', ans:10.2, tol:0.15, wrong:[[11.4,'SAI_MAU_SO'],[26,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['Giá mỗi chai = 229.000 ÷ 3 ≈ 76.333đ.','Chênh = 85.000 − 76.333 = 8.667đ.','8.667 ÷ 85.000 ≈ <b>10,2%</b>.'] },
  { type:'calc', stem:'Giá sàn 68.000đ, giá đại lý 85.000đ. Giá sàn thấp hơn giá đại lý bao nhiêu phần trăm?',
    unit:'%', ans:20, tol:0.1, wrong:[[25,'SAI_MAU_SO'],[17,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO'],
    steps:['Chênh = 85.000 − 68.000 = 17.000đ.','17.000 ÷ 85.000 = <b>20%</b> (chia cho giá đại lý, không phải giá sàn).'] },
  { type:'mcq', stem:'Một đại lý lớn ở Cần Thơ bán lên sàn với giá 70.000đ, thấp hơn khuyến nghị. Hãng nên nghĩ thế nào trước tiên?',
    options:[{k:'a',t:'Đại lý có quyền tự định giá; hãng không liên quan gì cả'},{k:'b',t:'Cắt hàng ngay lập tức để răn đe các đại lý còn lại'},
             {k:'c',t:'Giảm giá shop chính hãng xuống 69.000đ để giữ vị trí rẻ nhất'},{k:'d',t:'Xem lại chính sách chiết khấu và thoả thuận kênh với đại lý'}],
    answer:'d', why:{a:'Hãng vẫn chịu hậu quả khi giá hỗn loạn; cần có chính sách kênh.',
      b:'Phản ứng mạnh khi chưa rõ nguyên nhân; có thể là do chiết khấu thưởng số lượng quá lớn.',
      c:'Đua giá với chính đại lý làm tình hình tệ hơn.',
      d:'Đúng. Tìm vì sao đại lý bán được giá đó (chiết khấu, hàng tồn) và sửa bằng thoả thuận rõ ràng, trong khuôn khổ pháp luật.'} },
  { type:'mcq', stem:'Vì sao combo 3 chai ít gây xung đột với đại lý hơn chai lẻ giảm giá?',
    options:[{k:'a',t:'Vì khách không tính được giá mỗi chai trong combo là bao nhiêu'},{k:'b',t:'Vì combo phục vụ nhu cầu mua trữ khác với mua lẻ tiện lợi'},
             {k:'c',t:'Vì đại lý không được phép bán combo nên không so sánh được'},{k:'d',t:'Vì sàn không hiển thị combo khi khách tìm tên sản phẩm'}],
    answer:'b', why:{a:'Khách tính được; nhưng họ chấp nhận rẻ hơn khi mua nhiều.',
      b:'Đúng. Lý do rẻ hơn rõ ràng (mua số lượng) và tình huống mua khác nhau.',
      c:'Không phải lý do; đại lý vẫn có thể bán theo thùng.',
      d:'Combo vẫn hiển thị bình thường.'} },
  { type:'mcq', stem:'Ngày đôi, sàn mời shop chính hãng giảm 25% chai lẻ trong 24 giờ. Cách phản hồi nào giữ được kỷ luật giá?',
    options:[{k:'a',t:'Tham gia bằng combo hoặc quà tặng kèm, giữ nguyên giá chai lẻ'},{k:'b',t:'Từ chối mọi chương trình của sàn để giữ uy tín với đại lý lâu dài'},
             {k:'c',t:'Tham gia giảm 25% chai lẻ vì chỉ có 24 giờ, đại lý không biết'},{k:'d',t:'Tham gia và bù đại lý bằng cách giảm giá bán buôn cả tháng đó'}],
    answer:'a', why:{a:'Đúng. Vẫn có mặt trong sự kiện nhưng không đụng giá tham chiếu của chai lẻ.',
      b:'Mất lưu lượng lớn của ngày đôi; có cách tham gia không phá giá.',
      c:'Ảnh chụp giá lan nhanh; khách tạp hoá vẫn nhớ "trên mạng rẻ hơn".',
      d:'Tốn kém cả tháng cho một ngày; giải quyết hậu quả thay vì tránh nó.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:kn03-10', skill:'measure', read:'7 phút', t:'Khi nào nên làm website bán hàng riêng?',
  situation:'Thương hiệu nến thơm của Ngọc bán 1.500 đơn/tháng trên sàn, giá trung bình 250.000đ, tổng phí sàn và thanh toán khoảng 15% (minh hoạ). Một agency báo giá website 60 triệu, vận hành 8 triệu/tháng. Ngọc tính "15% phí sàn là 56 triệu/tháng, website rẻ hơn nhiều" và định chuyển hẳn.',
  concept:{ name:'Website là kênh sở hữu, không phải kênh miễn phí',
    body:'Website riêng bỏ được phí sàn, giữ được dữ liệu khách và toàn quyền kể câu chuyện thương hiệu. Nhưng nó <b>không có dòng khách sẵn</b>: mỗi lượt truy cập phải tự kéo bằng quảng cáo, nội dung hoặc khách cũ. Website đáng làm khi có ít nhất một trong ba: <b>khách mua lại nhiều</b> (có thể đưa về), <b>thương hiệu được tìm theo tên</b>, hoặc <b>sản phẩm cần kể nhiều</b> mà trang sàn không đủ chỗ. Đừng tính tiết kiệm trên toàn bộ doanh thu sàn; chỉ tính trên phần đơn thật sự chuyển được sang.' },
  example:'Phí trên 1.500 đơn: 1.500 × 250.000 × 15% = 56,25 triệu. Nhưng không phải 1.500 khách sẽ theo sang. Giả sử 20% là khách mua lại và chuyển được: 300 đơn tiết kiệm 300 × 37.500 = 11,25 triệu/tháng, trừ vận hành 8 triệu còn 3,25 triệu. 60 triệu ban đầu cần khoảng 19 tháng mới thu hồi. Ngọc giữ sàn làm kênh tìm khách mới, làm website nhỏ cho khách quen và quà tặng doanh nghiệp.',
  takeaway:'Website tiết kiệm phí trên đơn chuyển sang được, không trên toàn bộ doanh thu sàn.',
  apply:'Nói trong 60 giây: bao nhiêu phần trăm khách của bạn là khách quen, và họ có lý do gì để mua ở website thay vì sàn.',
  mistakes:['Tính tiết kiệm phí trên toàn bộ đơn sàn.','Bỏ sàn khi website chưa có nguồn khách riêng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: lỗi lớn nhất trong phép tính "website rẻ hơn 56 triệu phí sàn" là gì?',
    options:[{k:'a',t:'Quên rằng website cũng phải trả phí cổng thanh toán cho mỗi đơn'},{k:'b',t:'Giả định toàn bộ 1.500 đơn sẽ theo sang website'},
             {k:'c',t:'Agency báo giá 60 triệu là quá cao so với mặt bằng'},{k:'d',t:'Phí sàn thực tế luôn thấp hơn 15% nên tính quá tay'}],
    answer:'b', why:{a:'Có thật, nhưng là khoản nhỏ; lỗi lớn hơn nằm ở số đơn.',
      b:'Đúng. Phần lớn khách đến từ ô tìm kiếm của sàn; bỏ sàn là mất họ.',
      c:'Giá có thể thương lượng, nhưng không phải lỗi logic chính.',
      d:'Mức phí là minh hoạ; lỗi không nằm ở con số phí.'} },
  { type:'mcq', stem:'Bạn là Ngọc. Bạn chọn phương án nào?',
    options:[{k:'a',t:'Chuyển hẳn sang website, tắt sàn để khách buộc phải đi theo'},{k:'b',t:'Chưa làm gì, vì đang bán tốt trên sàn thì cứ giữ nguyên như vậy'},
             {k:'c',t:'Làm website thật lớn, chạy quảng cáo kéo khách mới vào ngay'},{k:'d',t:'Giữ sàn tìm khách mới, website nhỏ cho khách quen và quà tặng'}],
    answer:'d', why:{a:'Khách không "buộc" đi theo; họ mua shop khác trên sàn.',
      b:'Bỏ qua lợi ích dữ liệu và kênh sở hữu khi đã có 20% khách quen.',
      c:'Kéo khách mới vào website thường đắt hơn trên sàn; chưa có số chứng minh.',
      d:'Đúng. Mỗi kênh một vai; website phục vụ nhóm có lý do chuyển sang.'} },
  { type:'calc', stem:'1.500 đơn/tháng, giá trung bình 250.000đ, phí 15% (minh hoạ). Tổng phí sàn mỗi tháng là bao nhiêu đồng?',
    unit:'đ', ans:56250000, tol:1000, wrong:[[375000000,'QUEN_CHI_PHI_BIEN_DOI'],[5625000,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Doanh thu = 1.500 × 250.000 = 375.000.000đ.','Phí = 15% × 375.000.000 = <b>56.250.000đ</b>.'] },
  { type:'calc', stem:'300 đơn chuyển sang website, mỗi đơn tiết kiệm 37.500đ phí. Vận hành website 8 triệu/tháng, đầu tư ban đầu 60 triệu. Sau bao nhiêu tháng thu hồi vốn? (làm tròn lên)',
    unit:'tháng', ans:19, tol:0.5, wrong:[[6,'QUEN_CHI_PHI_CO_DINH'],[2,'SAI_MAU_SO']], errors:['QUEN_CHI_PHI_CO_DINH'],
    steps:['Tiết kiệm = 300 × 37.500 = 11.250.000đ/tháng.','Trừ vận hành: 11.250.000 − 8.000.000 = 3.250.000đ/tháng.','60.000.000 ÷ 3.250.000 ≈ 18,5 → <b>19 tháng</b>.'] },
  { type:'mcq', stem:'Thương hiệu nào dưới đây có lý do mạnh nhất để đầu tư website riêng sớm?',
    options:[{k:'a',t:'Shop ốp lưng giá rẻ, đổi mẫu hằng tuần, hầu như không có khách quen'},{k:'b',t:'Shop đồ gia dụng mới mở, chưa ai biết tên, đang cần thêm đơn đầu'},
             {k:'c',t:'Hãng cà phê hạt bán theo gói tháng, 45% khách mua lại đều'},{k:'d',t:'Shop bán lại hàng nhiều hãng khác nhau, cạnh tranh bằng giá thấp'}],
    answer:'c', why:{a:'Không có khách quen để đưa về; website không có dòng khách.',
      b:'Chưa ai tìm tên; cần sàn để có khách trước.',
      c:'Đúng. Mua lại đều đặn là nhóm khách chuyển được, và gói tháng hợp với kênh sở hữu.',
      d:'Khách đến vì giá, sẽ ở lại nơi so giá dễ nhất là sàn.'} },
  { type:'mcq', stem:'Website đã chạy 3 tháng, chỉ 40 đơn/tháng thay vì 300. Bạn kiểm tra điều gì trước?',
    options:[{k:'a',t:'Khách quen có biết website và có lý do để mua ở đó không'},{k:'b',t:'Tốc độ tải trang chậm làm khách thoát trước khi kịp đặt hàng'},
             {k:'c',t:'Giao diện chưa đủ đẹp so với trang của các thương hiệu lớn'},{k:'d',t:'Cần chạy thêm quảng cáo kéo khách mới vào nhiều hơn nữa'}],
    answer:'a', why:{a:'Đúng. Kế hoạch dựa vào khách quen chuyển sang; kiểm tra họ có biết và có lợi ích gì khi mua ở website không (quà, đóng gói riêng, gói tháng).',
      b:'Có thể là một nguyên nhân, nhưng trước hết phải biết có người đến hay không.',
      c:'Đẹp chưa phải lý do mua; chưa có dữ kiện nói giao diện là vấn đề.',
      d:'Kéo khách mới là mô hình khác, đắt hơn; kế hoạch gốc là khách quen.'} },
  { type:'mcq', stem:'Ngoài tiết kiệm phí, giá trị nào của website thường bị bỏ qua khi chỉ tính tiền?',
    options:[{k:'a',t:'Website giúp thương hiệu tự động lên đầu trang tìm kiếm Google'},{k:'b',t:'Website giúp tránh hoàn toàn chuyện bị đối thủ sao chép sản phẩm'},
             {k:'c',t:'Website được miễn mọi loại thuế so với bán hàng qua các sàn'},{k:'d',t:'Dữ liệu khách của chính bạn và chỗ kể câu chuyện thương hiệu đủ dài'}],
    answer:'d', why:{a:'Có website không có nghĩa tự lên đầu Google; phải làm nội dung và SEO.',
      b:'Website không ngăn được sao chép.',
      c:'Không có căn cứ; nghĩa vụ thuế không phụ thuộc kênh theo cách đó.',
      d:'Đúng. Dữ liệu và chỗ kể chuyện là tài sản lâu dài mà trang sàn không cho.'} }
  ] }

]});
